  ```css
  @media (max-width: 599.98px) {
    .login-page { gap: var(--space-5); padding: max(var(--space-6), env(safe-area-inset-top, 0px)) var(--space-4) max(var(--space-6), env(safe-area-inset-bottom, 0px)); }
